function fmt(q, unit) {
  if (unit === 'piece') return String(q);
  if (unit === 'g') {
    return q >= 454 ? (q / 454).toFixed(q % 454 === 0 ? 0 : 1) + ' lb'
                    : Math.round(q / 28) + ' oz';
  }
  if (unit === 'ml') {
    if (q >= 3785) return (q / 3785).toFixed(1) + ' gal';
    if (q >= 946)  return (q / 946).toFixed(1) + ' qt';
    return Math.round(q / 30) + ' fl oz';
  }
  return q + ' ' + unit;
}

const src = $('show-pantry').first().json;
const wanted = (src.query_items || '').split(',').map(s => s.trim()).filter(Boolean);
const filter = src.query_filter || 'in_stock';

let rows = $input.all().map(i => i.json).filter(r => r.item);

if (wanted.length) {
  rows = rows.filter(r => wanted.includes(r.item));
}
if (filter === 'in_stock')      rows = rows.filter(r => r.quantity > 0);
if (filter === 'out_of_stock')  rows = rows.filter(r => r.quantity === 0);

let reply;

if (wanted.length && rows.length === 0) {
  reply = `You have no ${wanted.join(' or ')}.`;
} else if (wanted.length) {
  reply = rows.map(r => `${r.item}: ${fmt(r.quantity, r.unit)}`).join('\n');
} else if (rows.length === 0) {
  reply = filter === 'out_of_stock'
    ? "Nothing has run out. 👍"
    : "Your pantry is empty. Add something with:\n• add 2 kg rice";
} else {
  const title = filter === 'out_of_stock' ? '🛒 Out of stock' : '🥘 Your pantry';
  reply = `${title}\n\n${rows.map(r => `• ${r.item} — ${fmt(r.quantity, r.unit)}`).join('\n')}`;
}

return [{ json: { user_id: src.user_id, channel: src.channel, reply } }];
